<template>
  <section class="workspace-page space-y-5">
    <PageHeader :title="pageTitle" :description="pageDescription">
      <template #actions><ButtonLink v-if="view === 'catalog'" to="/workspace/sell/products/new"><Plus class="h-4 w-4" /> Add product</ButtonLink><ButtonLink v-else-if="view === 'promotions'" to="/workspace/sell/promotions/new"><Plus class="h-4 w-4" /> Create promotion</ButtonLink><ButtonLink variant="outline"  v-else-if="view === 'orders'" to="/workspace/sell/pos"><CreditCard class="h-4 w-4" /> Open POS</ButtonLink></template>
    </PageHeader>

    <template v-if="view === 'catalog'">
      <dl class="grid overflow-hidden rounded-xl border bg-card sm:grid-cols-3"><div v-for="(metric, index) in catalogMetrics" :key="metric.label" class="border-b p-4 last:border-b-0 sm:border-b-0 sm:p-5" :class="index < catalogMetrics.length - 1 ? 'sm:border-r' : ''"><div class="flex items-center justify-between gap-2"><dt class="text-xs font-bold uppercase tracking-[.1em] text-muted-foreground">{{ metric.label }}</dt><span class="grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-secondary text-primary"><component :is="metric.icon" class="h-4 w-4" aria-hidden="true" /></span></div><dd class="mt-2 text-2xl font-extrabold" :class="metric.tone">{{ metric.value }}</dd></div></dl>
      <div class="flex flex-col gap-3 rounded-xl border bg-card p-3 sm:flex-row sm:items-center"><div class="relative min-w-0 flex-1"><Search class="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><label class="sr-only" for="catalog-search">Search products and services</label><Input id="catalog-search" v-model.trim="search" class="!pl-10" placeholder="Search products and services" @keyup.enter="applyFilters" /></div><label class="sr-only" for="catalog-type">Type</label><NativeSelect id="catalog-type" v-model="typeFilter" class="sm:max-w-44" @change="applyFilters"><option value="">All types</option><option value="physical">Physical</option><option value="digital">Digital</option><option value="service">Service</option></NativeSelect><label class="sr-only" for="catalog-status">Status</label><NativeSelect id="catalog-status" v-model="statusFilter" class="sm:max-w-44" @change="applyFilters"><option value="">All statuses</option><option value="draft">Draft</option><option value="published">Published</option><option value="archived">Archived</option></NativeSelect><Button variant="outline" type="button" @click="applyFilters">Filter</Button><div class="inline-flex shrink-0 rounded-lg border bg-muted/40 p-1" aria-label="Catalog view"><Button variant="ghost" class="grid h-8 w-8 place-items-center rounded-md" :class="displayMode === 'grid' ? 'bg-card text-foreground shadow-sm' : 'text-muted-foreground'" type="button" aria-label="Grid view" :aria-pressed="displayMode === 'grid'" @click="displayMode = 'grid'"><LayoutGrid class="h-4 w-4" /></Button><Button variant="ghost" class="grid h-8 w-8 place-items-center rounded-md" :class="displayMode === 'table' ? 'bg-card text-foreground shadow-sm' : 'text-muted-foreground'" type="button" aria-label="Table view" :aria-pressed="displayMode === 'table'" @click="displayMode = 'table'"><List class="h-4 w-4" /></Button></div></div>
    </template>

    <template v-else-if="view === 'promotions'">
      <dl class="grid overflow-hidden rounded-xl border bg-card sm:grid-cols-3"><div v-for="(metric, index) in promotionMetrics" :key="metric.label" class="border-b p-5 sm:border-b-0" :class="index < promotionMetrics.length - 1 ? 'sm:border-r' : ''"><div class="flex items-center justify-between gap-3"><dt class="text-sm font-semibold text-muted-foreground">{{ metric.label }}</dt><span class="grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-secondary text-primary"><component :is="metric.icon" class="h-4 w-4" aria-hidden="true" /></span></div><dd class="mt-2 text-2xl font-extrabold" :class="metric.tone">{{ metric.value }}</dd></div></dl>
      <div class="flex flex-col gap-3 rounded-xl border bg-card p-3 sm:flex-row"><div class="relative flex-1"><Search class="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><label class="sr-only" for="promotion-search">Search promotions</label><Input id="promotion-search" v-model.trim="search" class="!pl-10" placeholder="Search name or code" /></div><NativeSelect v-model="promotionState" class="sm:max-w-44" aria-label="Promotion status"><option value="">All statuses</option><option value="active">Active</option><option value="scheduled">Scheduled</option><option value="ended">Ended</option><option value="inactive">Inactive</option></NativeSelect></div>
    </template>

    <StatePanel v-if="loading" kind="loading" :title="`Loading ${pageTitle.toLowerCase()}`" message="Retrieving the latest business records." />
    <StatePanel v-else-if="error" kind="error" :title="`${pageTitle} unavailable`" :message="error"><Button variant="outline" type="button" @click="load">Try again</Button></StatePanel>

    <template v-else-if="view === 'catalog'">
      <StatePanel v-if="!items.length" title="No products or services yet" message="Create your first sellable item in a full-page product workspace."><ButtonLink to="/workspace/sell/products/new" class="mt-5">Add your first product</ButtonLink></StatePanel>
      <div v-else-if="displayMode === 'grid'" class="grid gap-5 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4"><article v-for="item in items" :key="item.public_id" class="group overflow-hidden rounded-xl border bg-card"><NuxtLink :to="`/workspace/sell/catalog/${item.public_id}`" class="block overflow-hidden"><ProductArtwork :name="item.name" :type="item.offering_type" :media="item.media" /><div class="p-5"><div class="flex items-start justify-between gap-4"><div class="min-w-0"><h2 class="truncate font-extrabold group-hover:text-primary">{{ item.name }}</h2><p class="mt-1 text-xs capitalize text-muted-foreground">{{ item.offering_type }} · {{ item.fulfillment_type.replaceAll('_', ' ') }}</p></div><StatusPill :value="item.status" /></div><p class="mt-4 line-clamp-2 min-h-10 text-sm leading-5 text-muted-foreground">{{ item.summary || 'No customer-facing summary yet.' }}</p><div class="mt-5 flex items-end justify-between gap-4 border-t pt-4"><div><p class="text-xs text-muted-foreground">Price</p><p class="mt-1 text-lg font-extrabold tabular-nums">{{ money(item.base_price) }}</p></div><div class="text-right"><p class="text-xs text-muted-foreground">Variants</p><p class="mt-1 font-bold">{{ item.variants.length }}</p></div></div></div></NuxtLink></article></div>
      <div v-else class="overflow-x-auto rounded-xl border bg-card"><Table class="w-full min-w-[56rem] text-left text-sm"><TableHeader class="bg-muted/45 text-xs text-muted-foreground"><TableRow><TableHead class="px-5 py-3 font-bold">Product or service</TableHead><TableHead class="px-4 py-3 font-bold">Type</TableHead><TableHead class="px-4 py-3 font-bold">SKU</TableHead><TableHead class="px-4 py-3 text-right font-bold">Price</TableHead><TableHead class="px-4 py-3 text-right font-bold">Variants</TableHead><TableHead class="px-4 py-3 font-bold">Status</TableHead><TableHead class="px-5 py-3 text-right font-bold">Action</TableHead></TableRow></TableHeader><TableBody class="divide-y"><TableRow v-for="item in items" :key="item.public_id"><TableCell class="px-5 py-3"><div class="flex items-center gap-3"><ProductArtwork :name="item.name" :type="item.offering_type" :media="item.media" size="thumb" /><div><p class="font-bold">{{ item.name }}</p><p class="mt-1 max-w-xs truncate text-xs text-muted-foreground">{{ item.summary || 'No summary' }}</p></div></div></TableCell><TableCell class="px-4 py-3 capitalize">{{ item.offering_type }}</TableCell><TableCell class="px-4 py-3 text-muted-foreground">{{ item.sku || '—' }}</TableCell><TableCell class="px-4 py-3 text-right font-bold">{{ money(item.base_price) }}</TableCell><TableCell class="px-4 py-3 text-right">{{ item.variants.length }}</TableCell><TableCell class="px-4 py-3"><StatusPill :value="item.status" /></TableCell><TableCell class="px-5 py-3 text-right"><NuxtLink :to="`/workspace/sell/catalog/${item.public_id}`" class="text-sm font-bold text-primary hover:underline">Manage</NuxtLink></TableCell></TableRow></TableBody></Table></div>
    </template>

    <template v-else-if="view === 'promotions'">
      <StatePanel v-if="!filteredPromotions.length" title="No promotions match this view" message="Create a campaign with a code, schedule, and product scope from its own page."><ButtonLink to="/workspace/sell/promotions/new" class="mt-5">Create promotion</ButtonLink></StatePanel>
      <div v-else class="overflow-x-auto rounded-xl border bg-card"><Table class="w-full min-w-[62rem] text-left text-sm"><TableHeader class="bg-muted/45 text-xs text-muted-foreground"><TableRow><TableHead class="px-5 py-3 font-bold">Promotion</TableHead><TableHead class="px-4 py-3 font-bold">Customer value</TableHead><TableHead class="px-4 py-3 font-bold">Code</TableHead><TableHead class="px-4 py-3 font-bold">Schedule</TableHead><TableHead class="px-4 py-3 font-bold">Applies to</TableHead><TableHead class="px-5 py-3 font-bold">Status</TableHead></TableRow></TableHeader><TableBody class="divide-y"><TableRow v-for="item in filteredPromotions" :key="item.public_id"><TableCell class="px-5 py-4"><p class="font-bold">{{ item.name }}</p><p class="mt-1 text-xs text-muted-foreground">Updated {{ formatDate(item.updated_at) }}</p></TableCell><TableCell class="px-4 py-4 font-extrabold text-primary">{{ item.value_type === 'percentage' ? `${Number(item.value)}% off` : `${money(item.value)} off` }}</TableCell><TableCell class="px-4 py-4"><code v-if="item.code" class="rounded bg-muted px-2 py-1 text-xs font-bold">{{ item.code }}</code><span v-else class="text-muted-foreground">Automatic</span></TableCell><TableCell class="px-4 py-4 text-muted-foreground">{{ promotionSchedule(item) }}</TableCell><TableCell class="px-4 py-4">{{ item.offering_ids?.length ? `${item.offering_ids.length} selected` : 'All products' }}</TableCell><TableCell class="px-5 py-4"><StatusPill :value="promotionStatus(item)" /></TableCell></TableRow></TableBody></Table></div>
    </template>

    <template v-else>
      <form class="flex flex-col gap-3 rounded-xl border bg-card p-3 sm:flex-row" @submit.prevent="applyFilters"><div class="relative flex-1"><Search class="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><label class="sr-only" for="record-search">Search {{ pageTitle.toLowerCase() }}</label><Input id="record-search" v-model.trim="search" class="!pl-10" :placeholder="`Search ${pageTitle.toLowerCase()}`" /></div><Button variant="outline" type="submit">Search</Button></form>
      <StatePanel v-if="!items.length" :title="`No ${pageTitle.toLowerCase()} yet`" :message="emptyMessage" />
      <div v-else class="overflow-x-auto rounded-xl border bg-card"><Table class="w-full min-w-[50rem] text-left text-sm"><TableHeader class="bg-muted/45 text-xs text-muted-foreground"><TableRow v-if="view === 'orders'"><TableHead class="px-5 py-3 font-bold">Order</TableHead><TableHead class="px-4 py-3 font-bold">Customer</TableHead><TableHead class="px-4 py-3 font-bold">Fulfillment</TableHead><TableHead class="px-4 py-3 font-bold">Payment</TableHead><TableHead class="px-5 py-3 text-right font-bold">Total</TableHead></TableRow><TableRow v-else><TableHead class="px-5 py-3 font-bold">Customer</TableHead><TableHead class="px-4 py-3 font-bold">Email</TableHead><TableHead class="px-4 py-3 font-bold">Phone</TableHead><TableHead class="px-5 py-3 font-bold">Created</TableHead></TableRow></TableHeader><TableBody class="divide-y"><TableRow v-for="item in items" :key="item.public_id"><template v-if="view === 'orders'"><TableCell class="px-5 py-4"><p class="font-bold">{{ item.number }}</p><p class="mt-1 text-xs text-muted-foreground">{{ formatDate(item.placed_at) }}</p></TableCell><TableCell class="px-4 py-4">{{ customerName(item) }}</TableCell><TableCell class="px-4 py-4 capitalize text-muted-foreground">{{ item.fulfillment_type }}</TableCell><TableCell class="px-4 py-4"><StatusPill :value="item.payment_status" /></TableCell><TableCell class="px-5 py-4 text-right font-extrabold">{{ money(item.grand_total) }}</TableCell></template><template v-else><TableCell class="px-5 py-4 font-bold">{{ [item.first_name, item.last_name].filter(Boolean).join(' ') || 'Guest customer' }}</TableCell><TableCell class="px-4 py-4 text-muted-foreground">{{ item.email }}</TableCell><TableCell class="px-4 py-4 text-muted-foreground">{{ item.phone || '—' }}</TableCell><TableCell class="px-5 py-4 text-muted-foreground">{{ formatDate(item.created_at) }}</TableCell></template></TableRow></TableBody></Table></div>
    </template>
  </section>
</template>

<script setup>
definePageMeta({ middleware: [(to) => {
  if (to.query.view === 'promotions') {
    const { view, ...query } = to.query
    return navigateTo({ path: '/workspace/sell/promotions', query }, { replace: true })
  }
  if (to.query.view === 'orders') {
    const { view, ...query } = to.query
    return navigateTo({ path: '/workspace/orders', query }, { replace: true })
  }
}] })
import { BadgeCheck, CalendarClock, CircleAlert, CreditCard, LayoutGrid, List, Package, Plus, Search, Tags } from 'lucide-vue-next'
const route = useRoute(); const router = useRouter(); const business = useBusinessStore(); const { apiFetch } = useApiClient(); const allowed = ['catalog', 'promotions', 'orders', 'customers']; const view = computed(() => allowed.includes(String(route.query.view)) ? String(route.query.view) : 'catalog')
const pageTitle = computed(() => ({ catalog: 'Products & services', promotions: 'Promotions', orders: 'Orders', customers: 'Customers' }[view.value])); const pageDescription = computed(() => ({ catalog: 'Manage what your business sells from a visual catalog. Products, digital goods, and bookable services share one dependable record.', promotions: 'Plan discount codes and automatic offers across your catalog and point of sale.', orders: 'Track payment and fulfillment across online checkout and point-of-sale orders.', customers: 'Review customer records created through checkout and booking activity.' }[view.value]))
const items = ref([]); const loading = ref(true); const error = ref(''); const search = ref(String(route.query.search || '')); const typeFilter = ref(String(route.query.type || '')); const statusFilter = ref(String(route.query.status || '')); const promotionState = ref(''); const displayMode = ref('grid')
const catalogSummary = computed(() => ({ total: items.value.length, published: items.value.filter((item) => item.status === 'published').length, needsAttention: items.value.filter((item) => item.status !== 'published' || !item.summary || !item.media?.length).length })); const now = computed(() => Date.now()); const activePromotions = computed(() => items.value.filter((item) => promotionStatus(item) === 'active').length); const scheduledPromotions = computed(() => items.value.filter((item) => promotionStatus(item) === 'scheduled').length); const filteredPromotions = computed(() => items.value.filter((item) => { const query = search.value.toLowerCase(); return (!query || `${item.name} ${item.code}`.toLowerCase().includes(query)) && (!promotionState.value || promotionStatus(item) === promotionState.value) }))
const catalogMetrics = computed(() => [
  { label: 'All offerings', value: catalogSummary.value.total, icon: Package, tone: '' },
  { label: 'Published', value: catalogSummary.value.published, icon: BadgeCheck, tone: 'text-primary' },
  { label: 'Needs attention', value: catalogSummary.value.needsAttention, icon: CircleAlert, tone: '' },
])
const promotionMetrics = computed(() => [
  { label: 'All promotions', value: items.value.length, icon: Tags, tone: '' },
  { label: 'Active now', value: activePromotions.value, icon: BadgeCheck, tone: 'text-primary' },
  { label: 'Scheduled', value: scheduledPromotions.value, icon: CalendarClock, tone: '' },
])
const emptyMessage = computed(() => view.value === 'orders' ? 'Orders will appear after online checkout or a point-of-sale transaction.' : 'Checkout and bookings create or match customer records here.')
watch(() => [route.query.view, route.query.search, route.query.type, route.query.status, business.activeBusiness?.public_id], load); onMounted(async () => { if (!business.activeBusiness) await business.loadBusinesses(); await load() })
async function applyFilters() { await router.push({ query: { view: view.value, ...(search.value && { search: search.value }), ...(typeFilter.value && { type: typeFilter.value }), ...(statusFilter.value && { status: statusFilter.value }) } }) }
async function load() { if (!business.activeBusiness) return; loading.value = true; error.value = ''; try { const resource = { catalog: 'offerings', promotions: 'discounts', orders: 'orders', customers: 'customers' }[view.value]; const query = new URLSearchParams({ page_size: '100' }); if (route.query.search && view.value === 'catalog') query.set('search', String(route.query.search)); if (route.query.type && view.value === 'catalog') query.set('offering_type', String(route.query.type)); if (route.query.status && view.value === 'catalog') query.set('status', String(route.query.status)); const response = await apiFetch(`businesses/${business.activeBusiness.public_id}/${resource}/?${query}`); items.value = response.results || [] } catch (requestError) { error.value = requestError?.data?.error?.message || `Could not load ${pageTitle.value.toLowerCase()}.` } finally { loading.value = false } }
function promotionStatus(item) { if (!item.is_active) return 'inactive'; if (item.starts_at && new Date(item.starts_at).getTime() > now.value) return 'scheduled'; if (item.ends_at && new Date(item.ends_at).getTime() < now.value) return 'ended'; return 'active' }
function promotionSchedule(item) { if (!item.starts_at && !item.ends_at) return 'Always available'; if (item.starts_at && item.ends_at) return `${formatDate(item.starts_at)} – ${formatDate(item.ends_at)}`; return item.starts_at ? `Starts ${formatDate(item.starts_at)}` : `Ends ${formatDate(item.ends_at)}` }
function customerName(order) { const customer = order.customer_snapshot || {}; return [customer.first_name, customer.last_name].filter(Boolean).join(' ') || customer.email || 'Guest customer' }
function money(value) { return new Intl.NumberFormat('en-PH', { style: 'currency', currency: business.activeBusiness?.currency || 'PHP' }).format(Number(value || 0)) }
function formatDate(value) { return value ? new Intl.DateTimeFormat('en-PH', { dateStyle: 'medium' }).format(new Date(value)) : '—' }
</script>
